const names = String($('Run Inputs').first().json.participant_names || '')
  .split(',').map(s => s.trim()).filter(Boolean)
  .sort((a, b) => b.length - a.length);
const emailRe = /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+([.][A-Za-z0-9-]+)+/g;
const phoneRes = [/[+][0-9][0-9 -]{8,}[0-9]/g, /(?<![0-9])[0-9]{5}[ -][0-9]{5}(?![0-9])/g, /(?<![0-9])[0-9]{3}[ -][0-9]{3}[ -][0-9]{4}(?![0-9])/g];
function isWord(ch) { return !!ch && /[\p{L}\p{M}\p{N}]/u.test(ch); }
function redactName(text, name) {
  let low = text.toLowerCase();
  let key = name.toLowerCase();
  if (low.length !== text.length) { low = text; key = name; }
  let out = '';
  let i = 0;
  let n = 0;
  while (i < text.length) {
    const j = low.indexOf(key, i);
    if (j === -1) { out += text.slice(i); break; }
    const before = j > 0 ? text[j - 1] : '';
    const after = j + key.length < text.length ? text[j + key.length] : '';
    if (!isWord(before) && !isWord(after)) { out += text.slice(i, j) + '[participant]'; n++; i = j + key.length; }
    else { out += text.slice(i, j + 1); i = j + 1; }
  }
  return { text: out, n };
}
return $input.all().map(item => {
  let t = String(item.json.text || '');
  let n = 0;
  t = t.replace(emailRe, () => { n++; return '[email]'; });
  for (const re of phoneRes) { t = t.replace(re, () => { n++; return '[phone]'; }); }
  for (const name of names) { const r = redactName(t, name); t = r.text; n += r.n; }
  return { json: { ...item.json, text: t, redactions: n } };
});

const cfg = $('Run Inputs').first().json;
const maxChars = Number(cfg.max_chunk_chars) || 180;
const cap = Math.min(Number(cfg.max_chunks) || 40, Math.floor(Number(cfg.token_budget) / Number(cfg.tokens_per_chunk)));
function stripBrackets(s) {
  let out = '';
  let depth = 0;
  for (const ch of s) {
    if (ch === '[') { depth++; }
    else if (ch === ']') { if (depth > 0) { depth--; } }
    else if (depth === 0) { out += ch; }
  }
  return out;
}
function pieces(sentence) {
  if (sentence.length <= maxChars) { return [sentence]; }
  const out = [];
  let cur = '';
  for (const w of sentence.split(' ')) {
    if (w.length > maxChars) {
      if (cur) { out.push(cur); cur = ''; }
      for (let k = 0; k < w.length; k += maxChars) { out.push(w.slice(k, k + maxChars)); }
    } else if (cur && (cur.length + 1 + w.length) > maxChars) { out.push(cur); cur = w; }
    else { cur = cur ? cur + ' ' + w : w; }
  }
  if (cur) { out.push(cur); }
  return out;
}
const perSource = [];
for (const item of $input.all()) {
  const j = item.json;
  const raw = j.url ? stripBrackets(String(j.text || '')) : String(j.text || '');
  const text = raw.split('\n').join(' ').replace(/ +/g, ' ').trim();
  const sentences = text.split(/(?<=[.!?]) +|(?<=[。！？])/).map(x => x.trim()).filter(Boolean);
  const chunks = [];
  let cur = '';
  for (const s of sentences) {
    for (const p of pieces(s)) {
      if (cur && (cur.length + 1 + p.length) > maxChars) { chunks.push(cur); cur = p; }
      else { cur = cur ? cur + ' ' + p : p; }
    }
  }
  if (cur) chunks.push(cur);
  perSource.push(chunks.filter(c => c.length >= 30).map((c, i) => ({ chunk_id: j.source_id + '-' + (i + 1), source_id: j.source_id, source_type: j.source_type, title: j.title || '', url: j.url || '', text: c })));
}
const out = [];
let round = 0;
let more = true;
while (more && out.length < cap) {
  more = false;
  for (const list of perSource) {
    if (round < list.length && out.length < cap) { out.push(list[round]); more = true; }
  }
  round++;
}
if (out.length === 0) { return [{ json: { no_text: true } }]; }
const available = perSource.reduce((a, l) => a + l.length, 0);
return out.map(c => ({ json: { ...c, chunks_available: available } }));

messageValues.message:
=You are a qualitative researcher. The user message lists text chunks from interviews, web pages and notes, each as chunk_id: text.
Propose between 3 and {{ $("Run Inputs").first().json.max_themes }} distinct themes that recur across the chunks. For each give theme_id (T1, T2, ...), a name of at most 6 words, and a one-sentence description. Use only what the chunks support. Do not invent themes.
Research focus: {{ $("Run Inputs").first().json.focus_question }}

parameters.jsCode:
const themes = $('Propose Themes').first().json.output?.themes || [];
const chunks = $('Chunk Text').all().map(i => i.json);
const byId = {};
for (const a of $input.all()) { if (a.json.chunk_id) { byId[a.json.chunk_id] = String(a.json.theme_id || '').trim(); } }
const buckets = {};
for (const t of themes) { buckets[t.theme_id] = { theme_id: t.theme_id, name: t.name, description: t.description, chunks: [] }; }
for (const c of chunks) {
  const tid = byId[c.chunk_id];
  if (tid && buckets[tid]) { buckets[tid].chunks.push(c); }
}
const result = Object.values(buckets)
  .filter(b => b.chunks.length > 0)
  .map(b => ({ json: { ...b, chunk_count: b.chunks.length, prompt_chunks: b.chunks.slice(0, 8) } }));
if (result.length === 0) { return [{ json: { no_placement: true } }]; }
return result;

const cfg = $('Run Inputs').first().json;
const chunks = $('Chunk Text').all().map(i => i.json);
const byChunk = {};
for (const c of chunks) { byChunk[c.chunk_id] = c; }
const groups = $('Group By Theme').all().map(i => i.json);
const byTheme = {};
for (const g of groups) { byTheme[g.theme_id] = g; }
const themes = $input.all().map(i => i.json).map(r => {
  const g = byTheme[r.theme_id] || { chunks: [], name: r.theme_id, description: '' };
  const memberIds = new Set(g.chunks.map(c => c.chunk_id));
  const asked = [...new Set(r.supporting_chunk_ids || [])];
  const quoteIds = asked.filter(id => memberIds.has(id));
  const quotes = quoteIds.map(id => ({ chunk_id: id, source_id: byChunk[id].source_id, source_type: byChunk[id].source_type, title: byChunk[id].title, url: byChunk[id].url, text: byChunk[id].text }));
  const bySource = {};
  const byType = {};
  for (const c of g.chunks) {
    bySource[c.source_id] = (bySource[c.source_id] || 0) + 1;
    byType[c.source_type] = (byType[c.source_type] || 0) + 1;
  }
  const flags = [];
  if (!r.ok) { flags.push('AI answer unreadable: write this insight by hand'); }
  if (quotes.length === 0) { flags.push('no valid supporting quote'); }
  if (asked.length > quoteIds.length) { flags.push((asked.length - quoteIds.length) + ' quote id(s) not in this theme were dropped'); }
  if (Object.keys(byType).length < 2) { flags.push('only one type of source supports this'); }
  return { theme_id: r.theme_id, theme: g.name, description: g.description, insight: r.insight, caveat: r.caveat, chunk_count: g.chunks.length, source_mix: bySource, source_types: byType, triangulated: Object.keys(byType).length >= 2, quotes, needs_review: flags.length > 0, flags };
});
const sources = $('All Sources').all().map(i => i.json);
const placed = groups.reduce((a, g) => a + g.chunk_count, 0);
const redactions = $('Anonymise').all().reduce((a, i) => a + (i.json.redactions || 0), 0);
const chars = chunks.reduce((a, c) => a + c.text.length, 0);
const available = chunks.length ? chunks[0].chunks_available : 0;
const batches = [];
for (let run = 0; run < 500; run++) {
  let items = [];
  try { items = $('Batch Result').all(0, run); } catch (e) { break; }
  if (!items.length) { break; }
  batches.push(items[0].json);
}
const batchesFailed = batches.filter(b => !b.batch_ok).length;
const calls = 1 + batches.length + themes.length;
const failedLinks = sources.filter(s => s.fetch_ok === false).map(s => s.url);
const skipped = $('Build Sources').first().json.links_skipped || 0;
const warnings = [];
if (batchesFailed > 0) { warnings.push(batchesFailed + ' of ' + batches.length + ' AI batches failed, so some text is in no theme. Submit again in a minute.'); }
if (themes.some(t => !t.insight)) { warnings.push('At least one insight could not be written. It is flagged below.'); }
if (failedLinks.length) { warnings.push('Could not read ' + failedLinks.length + ' link(s): ' + failedLinks.join(', ')); }
if (skipped) { warnings.push(skipped + ' line(s) under Web links did not start with http and were skipped.'); }
if (available > chunks.length) { warnings.push('Only ' + chunks.length + ' of ' + available + ' text pieces were analysed, to stay inside the token budget.'); }
const summary = {
  sources_requested: $('Split Sources').all().length,
  sources_with_text: sources.filter(s => String(s.text || '').length >= 30).length,
  sources_fetch_failed: failedLinks.length,
  links_skipped: skipped,
  chunks_available: available,
  chunks_used: chunks.length,
  chunks_placed_in_a_theme: placed,
  chunks_in_no_theme: chunks.length - placed,
  ai_batches: batches.length,
  ai_batches_failed: batchesFailed,
  themes: themes.length,
  themes_needing_review: themes.filter(t => t.needs_review).length,
  redactions_made: redactions,
  ai_calls: calls,
  est_tokens: Math.ceil(chars / 4) * 2 + calls * 1100
};
const cards = themes.map(t => ({ title: t.theme, text: t.insight, tags: Object.keys(t.source_types), evidence: t.quotes.map(q => q.source_id + ': ' + q.text), needs_review: t.needs_review }));
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
const themeHtml = themes.map(t => {
  const quotes = t.quotes.map(q => '<blockquote style="margin:8px 0;padding:6px 12px;border-left:3px solid #999">' + esc(q.text) + '<br><small>' + esc(q.title) + '</small></blockquote>').join('');
  const flags = t.flags.map(f => '<li>' + esc(f) + '</li>').join('');
  const flagHtml = flags ? '<p style="margin:8px 0 0;color:#8a4b00"><b>Check this:</b></p><ul style="margin:4px 0;color:#8a4b00">' + flags + '</ul>' : '';
  const limit = t.caveat ? '<p style="margin:0 0 8px"><small>Limit: ' + esc(t.caveat) + '</small></p>' : '';
  return '<div style="background:#fff;color:#1a1a1a;border:1px solid #ccc;border-radius:8px;padding:14px;margin:14px 0"><h2 style="margin:0 0 6px;font-size:18px">' + esc(t.theme) + '</h2><p style="margin:0 0 8px">' + esc(t.insight) + '</p>' + limit + quotes + flagHtml + '</div>';
}).join('');
const warnHtml = warnings.length ? '<div style="background:#fff4e0;color:#5c3a00;border-radius:8px;padding:10px 14px;margin:14px 0"><b>Please note</b><ul style="margin:6px 0">' + warnings.map(w => '<li>' + esc(w) + '</li>').join('') + '</ul></div>' : '';
const report_html = '<div style="max-width:760px;margin:0 auto;text-align:left;font-family:system-ui,sans-serif;line-height:1.5"><h1 style="font-size:22px;margin:0 0 6px">Insights</h1><p style="margin:0 0 6px">' + esc(cfg.focus_question) + '</p><p style="margin:0"><small>Sources read: ' + summary.sources_with_text + '. Text pieces: ' + chunks.length + '. Placed in a theme: ' + placed + '. Themes: ' + themes.length + '. Details hidden: ' + redactions + '. This is AI output: check every insight before you use it.</small></p>' + warnHtml + themeHtml + '<details style="margin:14px 0"><summary>Cards for Miro or FigJam (JSON)</summary><pre style="white-space:pre-wrap;font-size:12px">' + esc(JSON.stringify(cards, null, 2)) + '</pre></details></div>';
return [{ json: { summary, warnings, themes, miro_cards: cards, report_html } }];

