const j = $input.first().json;
function blocks(text) {
  return String(text || '').replace(/\r/g, '').split(/^ *-{3,} *$/m).map(s => s.trim()).filter(Boolean);
}
const sources = [];
blocks(j.transcripts_text).forEach((t, i) => sources.push({ source_id: 'T' + (i + 1), source_type: 'transcript', title: 'Transcript ' + (i + 1), text: t }));
blocks(j.other_text).forEach((t, i) => sources.push({ source_id: 'N' + (i + 1), source_type: 'text', title: 'Text ' + (i + 1), text: t }));
const lines = String(j.links || '').replace(/\r/g, '').split('\n').map(s => s.trim()).filter(Boolean);
const good = lines.filter(l => /^https?:\/\//i.test(l));
good.forEach((u, i) => sources.push({ source_id: 'W' + (i + 1), source_type: 'web', title: u, url: u }));
return [{ json: { sources, links_skipped: lines.length - good.length } }];
